<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\Template\Domain\ValueObject;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class TemplateEnabledVO
{
  public static function empty(): TemplateEnabledVO
  {
      return new TemplateEnabledVO(null);
  }
  public static function from(TemplateEnabledVO|bool|null $value): TemplateEnabledVO
  {
    return self::fromUnsafe($value);
  }
  public static function tryFrom(mixed $value, ConstraintFailList $list): ?TemplateEnabledVO
  {
    if ( $value instanceof TemplateEnabledVO ) {
      // If is a ValueObject, its already validated... nothing to append
      return $value;
    } else if( !$value ) {
      return new TemplateEnabledVO($value);
    } else if( is_bool($value)) {
      return new TemplateEnabledVO($value);
    } else {
      $list->add(new ConstraintFail('wrong_type', ['enabled'], [$value], ['bool']));
      return null;
    }
  }
  private static function fromUnsafe(mixed $value): TemplateEnabledVO
  {
    if ($value instanceof TemplateEnabledVO) {
      // If is a ValueObject, its already validated
      return $value;
    } else {
      // If is not a ValueObject, validation is need and exception throw
      $errorsList = new ConstraintFailList();
      $candidate = self::tryFrom($value, $errorsList);
      if ($errorsList->hasErrors()) {
        throw $errorsList->asConstraintException();
      }
      \assert($candidate instanceof TemplateEnabledVO);
      return $candidate;
    }
  }
  /**
   * private constructor to avoid build a value without all the rule validations.
   */
  private function __construct(
    private readonly ?bool $enabled
  ) {
  }
  public function value(): ?bool
  {
    return $this->enabled;
  }
  public function equals(?TemplateEnabledVO $other): bool
  {
    return $this->value() == $other?->value();
  }
}
